import aiohttp

async def fetch(url):
    async with aiohttp.ClientSession() as session:
        r = session.get(url)
        return await r.text()

def get_data(urls):
    tasks = [fetch(u) for u in urls]
    return asyncio.run(tasks)

print(get_data(['https://example.com', 'https://example.org']))
